export async function fetchHiraHospitalResources(params) {
    const cleanSgg = params.sgg.trim();
    const stat = MOCK_HIRA_STATS[cleanSgg] || {
        시군구명: cleanSgg,
        전체의사수: 35,
        전문의수: 22,
        핵심_필수의료_전문의: { 산부인과: 1, 소아청소년과: 1, 응급의학과: 1, 외과: 2, 흉부외과: 0 },
        필수의료_병상수: { 분만실_인가병상: 0, 소아전용_인가병상: 2, 중환자실_병상: 4, 응급실_병상: 10 },
        인구_1000명당_의사수: 0.95,
        전국평균_의사수_대비_비율: 43.5,
        분만_의료기관_존재여부: false,
    };
    return {
        데이터_출처: '건강보험심사평가원(HIRA) 의료기관 및 전문의 자원 통계',
        지자체: cleanSgg,
        의사인력_현황: {
            전체의사수: `${stat.전체의사수}명`,
            전문의수: `${stat.전문의수}명`,
            인구_1000명당_의사수: `${stat.인구_1000명당_의사수}명 (전국 평균 2.18명 대비 ${stat.전국평균_의사수_대비_비율}%)`,
        },
        핵심_필수의료_전문의_분포: stat.핵심_필수의료_전문의,
        필수의료_병상_현황: stat.필수의료_병상수,
        분만실_운영여부: stat.분만_의료기관_존재여부 ? '관내 분만실 인가 운영 중' : '관내 분만실 부재 (외래만 운영 또는 원정 분만)',
        자원_진단_소견: !stat.분만_의료기관_존재여부
            ? '관내 분만실 전무로 인한 고위험 산모의 이송 공백 심각, 분만취약지 지원사업 시설 인프라 필수'
            : '필수의료 전문의 고령화 및 당직 인력 부족으로 24시간 필수의료 유지 애로',
    };
}
